mapper.select:
SELECT a.EVENT_ID, a.BUSINESS_RECORD_ID, a.BUSINESS_REPORT_TYPE, a.BUSINESS_RECORD_SUB_TYPE, a.BUSINESS_RECORD_VERSION, a.SOURCE, a.STATUS, a.DUPLICATE_EVENT_ID, a.DUPLICATE_CHECK_END_TIME, a.REPOST_PARENT_EVENT_ID, a.PROCESSING_HOST, a.STATUS_EXPIRY_TIME, a.CREATE_TIME, a.UPDATE_TIME, a.CREATE_BY, a.UPDATE_BY FROM ( SELECT b.EVENT_ID, b.BUSINESS_RECORD_ID, b.BUSINESS_REPORT_TYPE, b.BUSINESS_RECORD_SUB_TYPE, b.BUSINESS_RECORD_VERSION, b.SOURCE, b.STATUS, b.DUPLICATE_EVENT_ID, b.DUPLICATE_CHECK_END_TIME, b.REPOST_PARENT_EVENT_ID, b.PROCESSING_HOST, b.STATUS_EXPIRY_TIME, b.CREATE_TIME, b.UPDATE_TIME, b.CREATE_BY, b.UPDATE_BY, rownum rn FROM EVENT b
WHERE rownum <= (#{startPosition} + #{numberOfRecords} - 1)
AND b.EVENT_ID= #{event.eventId}
AND b.BUSINESS_RECORD_ID= #{event.businessRecordId}
AND b.BUSINESS_REPORT_TYPE= #{event.businessRecordType}
AND b.BUSINESS_RECORD_SUB_TYPE= #{event.businessRecordSubType}
AND b.BUSINESS_RECORD_VERSION= #{event.businessRecordVersion}
AND b.SOURCE= #{event.source}
AND b.STATUS= #{event.status}
AND b.PROCESSING_HOST= #{event.processingHost}
AND b.CREATE_BY= #{event.createBy}
AND b.UPDATE_BY= #{event.updateBy}
) a
WHERE a.rn >= #{startPosition} ORDER BY a.CREATE_TIME DESC

SELECT a.EVENT_ID, a.BUSINESS_RECORD_ID, a.BUSINESS_REPORT_TYPE, a.BUSINESS_RECORD_SUB_TYPE, a.BUSINESS_RECORD_VERSION, a.SOURCE, a.STATUS, a.DUPLICATE_EVENT_ID, a.DUPLICATE_CHECK_END_TIME, a.REPOST_PARENT_EVENT_ID, a.PROCESSING_HOST, a.STATUS_EXPIRY_TIME, a.CREATE_TIME, a.UPDATE_TIME, a.CREATE_BY, a.UPDATE_BY FROM ( SELECT b.EVENT_ID, b.BUSINESS_RECORD_ID, b.BUSINESS_REPORT_TYPE, b.BUSINESS_RECORD_SUB_TYPE, b.BUSINESS_RECORD_VERSION, b.SOURCE, b.STATUS, b.DUPLICATE_EVENT_ID, b.DUPLICATE_CHECK_END_TIME, b.REPOST_PARENT_EVENT_ID, b.PROCESSING_HOST, b.STATUS_EXPIRY_TIME, b.CREATE_TIME, b.UPDATE_TIME, b.CREATE_BY, b.UPDATE_BY, rownum rn FROM EVENT b
WHERE rownum <= (#{startPosition} + #{numberOfRecords}) AND b.DUPLICATE_CHECK_END_TIME > #{event.createTime} AND b.STATUS != 'ABORT'
AND b.BUSINESS_RECORD_ID= #{event.businessRecordId}
AND b.BUSINESS_REPORT_TYPE= #{event.businessRecordType}
AND b.BUSINESS_RECORD_SUB_TYPE= #{event.businessRecordSubType}
AND b.BUSINESS_RECORD_VERSION= #{event.businessRecordVersion}
) a
WHERE a.rn >= #{startPosition}


SELECT TARGET_ID
FROM EVENT_TARGET
WHERE EVENT_ID = #{EVENT_ID}

mapper.update:

UPDATE EVENT
SET STATUS =#{event.status},
    UPDATE_TIME = #{event.updateTime},
    UPDATE_BY = #{event.updateBy}
WHERE EVENT_ID = #{event.eventId}
